import type { ToolExample } from "../../core/example.js";
import { createSimpleTool, simpleError } from "../../core/simple.js";

const categories = {
  blackSwan: {
    definition:
      "An outlier outside regular expectations that has extreme impact and is commonly rationalized in hindsight.",
    distinguishingFeature:
      "unexpected outlier with retrospective explainability",
  },
  dragonKing: {
    definition:
      "An extreme event generated by mechanisms that differ from those producing ordinary events and that may exhibit detectable precursors.",
    distinguishingFeature:
      "distinct generating mechanism and possible precursors",
  },
  greyRhino: {
    definition:
      "A highly probable, high-impact threat that is visible yet neglected or insufficiently addressed.",
    distinguishingFeature: "obvious and probable but neglected",
  },
} as const;

export type EventRiskCategory = keyof typeof categories;

export type EventRiskTaxonomyInput = {
  readonly category: EventRiskCategory;
};

export type EventRiskTaxonomyOutput = {
  readonly category: EventRiskCategory;
  readonly definition: string;
  readonly distinguishingFeature: string;
};

export const lookupEventRiskTaxonomy = (
  input: EventRiskTaxonomyInput,
): EventRiskTaxonomyOutput => {
  const entry = categories[input.category];
  if (entry === undefined)
    simpleError(
      "category",
      "Risk-event category is not supported.",
      "unsupported_event_risk_category",
    );
  return { category: input.category, ...entry };
};

export const eventRiskTaxonomyExample = {
  input: { category: "greyRhino" },
  output: {
    category: "greyRhino",
    definition:
      "A highly probable, high-impact threat that is visible yet neglected or insufficiently addressed.",
    distinguishingFeature: "obvious and probable but neglected",
  },
} satisfies ToolExample<EventRiskTaxonomyInput, EventRiskTaxonomyOutput>;

export const eventRiskTaxonomyTool = createSimpleTool({
  calculate: (input) =>
    lookupEventRiskTaxonomy({ category: input.category as EventRiskCategory }),
  description:
    "Look up the distinguishing definition of black swan, grey rhino, and dragon-king events without pretending that a short trait checklist can classify a real event conclusively.",
  id: "futurology/black-swan-grey-rhino-dragon-king-taxonomy",
  inputs: [
    {
      enum: ["blackSwan", "dragonKing", "greyRhino"],
      id: "category",
      kind: "string",
      label: "Risk-event category",
    },
  ],
  outputs: [
    { id: "category", kind: "string", label: "Risk-event category" },
    { id: "definition", kind: "string", label: "Definition" },
    {
      id: "distinguishingFeature",
      kind: "string",
      label: "Distinguishing feature",
    },
  ],
  title: "Black Swan Grey Rhino Dragon King Taxonomy",
});

export const runEventRiskTaxonomy = eventRiskTaxonomyTool.execute;
export default eventRiskTaxonomyTool;
